__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"ACCESS_SITE",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"ACCESS_CARDS",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"ACCESS_NOTE",{enumerable:!0,get:function(){return l}});const t='https://alharamain.gov.sa',n=[{icon:'wheel',title:{tr:'\xdccretsiz tekerlekli sandalye',en:'Free wheelchair',ar:'\u0643\u0631\u0633\u064a \u0645\u062a\u062d\u0631\u0643 \u0645\u062c\u0627\u0646\u064a'},text:{tr:'Ya\u015fl\u0131 ve engelliler i\xe7in 24 saat \xfccretsiz. Sandalyeyi yan\u0131n\u0131zdaki ki\u015fi iter. Teslim noktalar\u0131 do\u011fu avlusunda Sel\xe2m Kap\u0131s\u0131 (19) ve bat\u0131 avlusunda \u015eubeyke K\xf6pr\xfcs\xfc yan\u0131nda. \u0130\u015f bitince ayn\u0131 noktaya iade edilir. Ramazan ve hac g\xfcnlerinde sandalye bitebilir; m\xfcmk\xfcnse katlan\u0131r bir sandalye getirin.',en:'Free around the clock for the elderly and people with disabilities; your companion pushes it. Pick-up points: the eastern courtyard at Bab al-Salam (19) and the western courtyard by the Shubaika Bridge. Return it to the same point. In Ramadan and Hajj they can run out; bring a folding wheelchair if you can.',ar:'\u0645\u062c\u0627\u0646\u064b\u0627 \u0639\u0644\u0649 \u0645\u062f\u0627\u0631 \u0627\u0644\u0633\u0627\u0639\u0629 \u0644\u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 \u0648\u0630\u0648\u064a \u0627\u0644\u0625\u0639\u0627\u0642\u0629\u060c \u0648\u064a\u062f\u0641\u0639\u0647 \u0645\u0631\u0627\u0641\u0642\u0643. \u0646\u0642\u0627\u0637 \u0627\u0644\u062a\u0633\u0644\u064a\u0645: \u0627\u0644\u0633\u0627\u062d\u0629 \u0627\u0644\u0634\u0631\u0642\u064a\u0629 \u0639\u0646\u062f \u0628\u0627\u0628 \u0627\u0644\u0633\u0644\u0627\u0645 (19) \u0648\u0627\u0644\u0633\u0627\u062d\u0629 \u0627\u0644\u063a\u0631\u0628\u064a\u0629 \u0639\u0646\u062f \u062c\u0633\u0631 \u0627\u0644\u0634\u0628\u064a\u0643\u0629. \u064a\u064f\u0639\u0627\u062f \u0625\u0644\u0649 \u0627\u0644\u0646\u0642\u0637\u0629 \u0646\u0641\u0633\u0647\u0627. \u0642\u062f \u062a\u0646\u0641\u062f \u0641\u064a \u0631\u0645\u0636\u0627\u0646 \u0648\u0627\u0644\u062d\u062c\u060c \u0641\u0623\u062d\u0636\u0631 \u0643\u0631\u0633\u064a\u064b\u0627 \u0642\u0627\u0628\u0644\u064b\u0627 \u0644\u0644\u0637\u064a \u0625\u0646 \u0627\u0633\u062a\u0637\u0639\u062a.'}},{icon:'car',title:{tr:'Golf arabas\u0131 ve itici ile sandalye',en:'Golf cart or pushed wheelchair',ar:'\u0639\u0631\u0628\u0629 \u0627\u0644\u0642\u0648\u0644\u0641 \u0623\u0648 \u0627\u0644\u0639\u0631\u0628\u0629 \u0628\u062f\u0627\u0641\u0639'},text:{tr:'\xdccretli. Tavaf, sa\u2019y ya da tam umre i\xe7in g\xfcn ve saat se\xe7erek Haremeyn \u0130daresi\u2019nin \u201cBirle\u015fik Ula\u015f\u0131m Platformu\u201dndan \xf6nceden ay\u0131rt\u0131l\u0131r; golf arabalar\u0131 yaln\u0131z bu platformla ayr\u0131l\u0131r. 65 ya\u015f \xfcst\xfcne rezervasyon \xf6nerilir; yapamayanlar Harem\u2019deki hizmet noktalar\u0131na ba\u015fvurabilir. Noktalar Ecyad (Kral Abd\xfclaziz Kap\u0131s\u0131) taraf\u0131nda ve \u015eubeyke K\xf6pr\xfcs\xfc giri\u015finde. Biletinizi ve kimli\u011finizi yan\u0131n\u0131za al\u0131p saatinde gelin.',en:'Paid. Book ahead on the Authority\u2019s Unified Mobility Platform for tawaf, sa\u2018y or a full umrah at a chosen date and time; golf carts are booked only there. Booking is advised for those over 65; others can ask at service points in the mosque. Points are on the Ajyad side (King Abdulaziz Gate) and at the Shubaika Bridge entrance. Arrive on time with your ticket and ID.',ar:'\u0628\u0623\u062c\u0631. \u064a\u064f\u062d\u062c\u0632 \u0645\u0633\u0628\u0642\u064b\u0627 \u0639\u0628\u0631 \xab\u0645\u0646\u0635\u0629 \u0627\u0644\u062a\u0646\u0642\u0644 \u0627\u0644\u0645\u0648\u062d\u062f\u0629\xbb \u0627\u0644\u062a\u0627\u0628\u0639\u0629 \u0644\u0644\u0647\u064a\u0626\u0629 \u0644\u0644\u0637\u0648\u0627\u0641 \u0623\u0648 \u0627\u0644\u0633\u0639\u064a \u0623\u0648 \u0627\u0644\u0639\u0645\u0631\u0629 \u0643\u0627\u0645\u0644\u0629 \u0645\u0639 \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u064a\u0648\u0645 \u0648\u0627\u0644\u0648\u0642\u062a\u060c \u0648\u0644\u0627 \u062a\u064f\u062d\u062c\u0632 \u0639\u0631\u0628\u0627\u062a \u0627\u0644\u0642\u0648\u0644\u0641 \u0625\u0644\u0627 \u0639\u0628\u0631\u0647\u0627. \u064a\u064f\u0646\u0635\u062d \u0645\u0646 \u062a\u062c\u0627\u0648\u0632 65 \u0639\u0627\u0645\u064b\u0627 \u0628\u0627\u0644\u062d\u062c\u0632\u060c \u0648\u064a\u0645\u0643\u0646 \u0644\u063a\u064a\u0631\u0647\u0645 \u0645\u0631\u0627\u062c\u0639\u0629 \u0646\u0642\u0627\u0637 \u0627\u0644\u062e\u062f\u0645\u0629. \u0627\u0644\u0646\u0642\u0627\u0637 \u0641\u064a \u062c\u0647\u0629 \u0623\u062c\u064a\u0627\u062f (\u0628\u0627\u0628 \u0627\u0644\u0645\u0644\u0643 \u0639\u0628\u062f\u0627\u0644\u0639\u0632\u064a\u0632) \u0648\u0645\u062f\u062e\u0644 \u062c\u0633\u0631 \u0627\u0644\u0634\u0628\u064a\u0643\u0629. \u0627\u062d\u0636\u0631 \u0641\u064a \u0645\u0648\u0639\u062f\u0643 \u0648\u0645\u0639\u0643 \u0627\u0644\u062a\u0630\u0643\u0631\u0629 \u0648\u0627\u0644\u0647\u0648\u064a\u0629.'}},{icon:'aid',title:{tr:'Engelli ziyaret\xe7iler',en:'Visitors with disabilities',ar:'\u0630\u0648\u0648 \u0627\u0644\u0625\u0639\u0627\u0642\u0629'},text:{tr:'Engelli ziyaret\xe7i, rezervasyon yapmadan golf arabas\u0131 noktas\u0131na gidip bir refakat\xe7iyle \xfccretsiz yararlanabilir. Harem\u2019de engellilere ayr\u0131lm\u0131\u015f namaz alanlar\u0131 da var; yerini g\xf6revlilere sorun.',en:'A visitor with a disability can go straight to a golf-cart point and ride free with one companion, without booking. There are also prayer areas reserved for people with disabilities; ask the staff where they are.',ar:'\u064a\u0645\u0643\u0646 \u0644\u0630\u064a \u0627\u0644\u0625\u0639\u0627\u0642\u0629 \u0627\u0644\u062a\u0648\u062c\u0647 \u0645\u0628\u0627\u0634\u0631\u0629 \u0625\u0644\u0649 \u0646\u0642\u0637\u0629 \u0639\u0631\u0628\u0627\u062a \u0627\u0644\u0642\u0648\u0644\u0641 \u0648\u0627\u0644\u0627\u0633\u062a\u0641\u0627\u062f\u0629 \u0645\u062c\u0627\u0646\u064b\u0627 \u0645\u0639 \u0645\u0631\u0627\u0641\u0642 \u062f\u0648\u0646 \u062d\u062c\u0632. \u0648\u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0645\u0635\u0644\u064a\u0627\u062a \u0645\u062e\u0635\u0635\u0629 \u0644\u0630\u0648\u064a \u0627\u0644\u0625\u0639\u0627\u0642\u0629\u061b \u0627\u0633\u0623\u0644 \u0627\u0644\u0645\u0646\u0638\u0645\u064a\u0646 \u0639\u0646 \u0623\u0645\u0627\u0643\u0646\u0647\u0627.'}},{icon:'hotel',title:{tr:'Otelden alma',en:'Pick-up from your hotel',ar:'\u0627\u0644\u0646\u0642\u0644 \u0645\u0646 \u0627\u0644\u0641\u0646\u062f\u0642'},text:{tr:'Harem\u2019e yak\u0131n baz\u0131 otellerde araba ayn\u0131 platformdan otele \xe7a\u011fr\u0131labilir. G\xf6revli sizi tavafa ya da umreye g\xf6t\xfcr\xfcr; tam hizmette otele geri getirir.',en:'At some hotels near the mosque you can call a cart to the hotel on the same platform. A staff member takes you for tawaf or umrah and, with the full service, back to the hotel.',ar:'\u0641\u064a \u0628\u0639\u0636 \u0627\u0644\u0641\u0646\u0627\u062f\u0642 \u0627\u0644\u0642\u0631\u064a\u0628\u0629 \u064a\u0645\u0643\u0646 \u0637\u0644\u0628 \u0627\u0644\u0639\u0631\u0628\u0629 \u0625\u0644\u0649 \u0627\u0644\u0641\u0646\u062f\u0642 \u0639\u0628\u0631 \u0627\u0644\u0645\u0646\u0635\u0629 \u0646\u0641\u0633\u0647\u0627\u060c \u0648\u064a\u0631\u0627\u0641\u0642\u0643 \u0645\u0631\u0627\u0641\u0642 \u0645\u0639\u062a\u0645\u062f \u0644\u0644\u0637\u0648\u0627\u0641 \u0623\u0648 \u0627\u0644\u0639\u0645\u0631\u0629 \u062b\u0645 \u064a\u0639\u064a\u062f\u0643 \u0625\u0644\u0649 \u0627\u0644\u0641\u0646\u062f\u0642 \u0641\u064a \u0627\u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629.'}},{icon:'walk',title:{tr:'Sa\u2019y ve tavafta',en:'During sa\u2018y and tawaf',ar:'\u0641\u064a \u0627\u0644\u0633\u0639\u064a \u0648\u0627\u0644\u0637\u0648\u0627\u0641'},text:{tr:'Mes\u2019a\u2019da (Safa\u2013Merve) tekerlekli sandalyeler i\xe7in ayr\u0131 \u015ferit var. Kalabal\u0131kta tavaf\u0131 \xfcst katlarda yapmak daha rahatt\u0131r. Sandalye ya da arabayla tavaf ve sa\u2019y caizdir; ara vermek de caizdir.',en:'The Mas\u2018a (Safa\u2013Marwa) has a separate wheelchair lane. In crowds, tawaf on the upper floors is easier. Tawaf and sa\u2018y in a wheelchair or cart are valid, and resting in between is allowed.',ar:'\u0641\u064a \u0627\u0644\u0645\u0633\u0639\u0649 \u0645\u0633\u0627\u0631 \u0645\u062e\u0635\u0635 \u0644\u0644\u0643\u0631\u0627\u0633\u064a \u0627\u0644\u0645\u062a\u062d\u0631\u0643\u0629. \u0648\u0641\u064a \u0627\u0644\u0632\u062d\u0627\u0645 \u064a\u0643\u0648\u0646 \u0627\u0644\u0637\u0648\u0627\u0641 \u0641\u064a \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0627\u0644\u0639\u0644\u064a\u0627 \u0623\u064a\u0633\u0631. \u0648\u064a\u0635\u062d \u0627\u0644\u0637\u0648\u0627\u0641 \u0648\u0627\u0644\u0633\u0639\u064a \u0628\u0627\u0644\u0643\u0631\u0633\u064a \u0623\u0648 \u0627\u0644\u0639\u0631\u0628\u0629\u060c \u0648\u062a\u062c\u0648\u0632 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0629 \u0628\u064a\u0646\u0647\u0645\u0627.'}}],l={tr:'Bilgiler Haremeyn \u0130\u015fleri Genel Kurumu duyurular\u0131na dayan\u0131r (Suudi Bas\u0131n Ajans\u0131 ve bas\u0131n, 2024\u20132026; son kontrol Kas\u0131m 2026). Yerler ve kurallar sezona g\xf6re de\u011fi\u015febilir; g\xf6revlilere sorun.',en:'Based on announcements of the General Authority for the Care of the Two Holy Mosques (Saudi Press Agency and press, 2024\u20132026; last checked November 2026). Locations and rules change by season; ask the staff.',ar:'\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0645\u0646 \u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0647\u064a\u0626\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0644\u0639\u0646\u0627\u064a\u0629 \u0628\u0634\u0624\u0648\u0646 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u0648\u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u0646\u0628\u0648\u064a (\u0648\u0627\u0633 \u0648\u0627\u0644\u0635\u062d\u0627\u0641\u0629\u060c 2024\u20132026\u061b \u0622\u062e\u0631 \u0645\u0631\u0627\u062c\u0639\u0629 \u0646\u0648\u0641\u0645\u0628\u0631 2026). \u0642\u062f \u062a\u062a\u063a\u064a\u0631 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0648\u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0628\u062d\u0633\u0628 \u0627\u0644\u0645\u0648\u0633\u0645\u061b \u0627\u0633\u0623\u0644 \u0627\u0644\u0645\u0646\u0638\u0645\u064a\u0646.'}},921,[]);